const items = $input.all();
const normalized = [];
for (const item of items) {
  const d = item.json;
  let source="web", url="", content="", author="", ts="";
  if (d.link && d.link.includes("reddit.com")) { source="reddit"; url=d.link; content=d.snippet||d.title||""; author=d.title||""; }
  else if (d.text) { source="twitter"; url=`https://twitter.com/i/status/${d.id}`; content=d.text; author=d.author_id||""; ts=d.created_at||""; }
  else if (d.title) { source="rss"; url=d.link||""; content=d.title+" "+(d.contentSnippet||""); }
  if (content && url) normalized.push({ json: { source, url, content: content.substring(0,500), author, timestamp: ts||new Date().toISOString() }});
}
return normalized.length ? normalized : [{ json: { skip: true }}];

