const input = $input.first().json;
let profile;
try {
  const msg = input.content ? input.content[0].text : JSON.stringify(input);
  profile = JSON.parse(msg);
} catch(e) { profile = { fit_score: 50, engagement_score: 50 }; }
const lead = $("💾 Save New Lead").first().json;
const intent = lead.intent_score || 50;
const fit = profile.fit_score || 50;
const engagement = profile.engagement_score || 50;
const daysOld = 1;
const timing = daysOld < 1 ? 100 : daysOld < 3 ? 70 : daysOld < 7 ? 40 : 20;
const total = Math.round(intent*0.4 + fit*0.3 + engagement*0.2 + timing*0.1);
const classification = total >= 80 ? "HOT" : total >= 50 ? "WARM" : "COLD";
return [{ json: { ...lead, ...profile, fit_score: fit, engagement_score: engagement, timing_score: timing, total_score: total, classification, persona: profile.persona, pain_points: profile.pain_points, ai_approach: profile.recommended_approach, best_channel: profile.best_channel }}];

