const reply = $input.first().json;
const text = (reply.text_body || reply.body || "").toLowerCase();
let sentiment = "neutral";
if (text.match(/thanks|great|interested|love|yes|sure|sounds good|tell me more/)) sentiment = "positive";
else if (text.match(/stop|unsubscribe|not interested|remove|spam|no thanks/)) sentiment = "negative";
else if (text.includes("?")) sentiment = "question";
return [{ json: { ...reply, sentiment, original_text: text }}];

const leads = $input.all();
const results = [];
for (const item of leads) {
  const lead = item.json;
  if (!lead.id) continue;
  const detectedAt = new Date(lead.detected_at || lead.created_at || Date.now());
  const lastActivity = new Date(lead.last_action_date || detectedAt);
  const daysSinceActivity = Math.max(0, (Date.now() - lastActivity.getTime()) / 86400000);
  const decayRate = lead.email_opened ? 0.95 : 0.90;
  const currentScore = lead.total_score || lead.intent_score || 50;
  const decayedScore = Math.round(currentScore * Math.pow(decayRate, daysSinceActivity));
  let action = "WAIT";
  if (decayedScore < 15) action = "ARCHIVE";
  else if (daysSinceActivity > 3 && decayedScore > 30) action = "FOLLOW_UP";
  results.push({ json: { ...lead, decayed_score: decayedScore, days_inactive: Math.round(daysSinceActivity), original_score: currentScore, decay_action: action }});
}
return results.length ? results : [{ json: { skip: true }}];

